"""Identical FileResponse fixture for both exact Starlette revisions."""

from pathlib import Path

from starlette.responses import FileResponse

FIXTURE = Path(__file__).with_name("fixture.bin")


async def app(scope, receive, send):
    # Match upstream's regression: custom weak ETag, autogenerated Last-Modified.
    etag = 'W/"a_weak_etag"' if scope["path"] == "/weak" else '"strong-control"'
    await FileResponse(FIXTURE, headers={"etag": etag})(scope, receive, send)
